class MainActivity:ComponentActivity(){override fun onCreate(b:Bundle?){super.onCreate(b);setContent{UI({startActivity(Intent(Settings.ACTION_MANAGE_OVERLAY_PERMISSION,Uri.parse("package:$packageName")))},{startActivity(Intent(Settings.ACTION_ACCESSIBILITY_SETTINGS))},{startForegroundService(Intent(this,BubbleService::class.java))})}}}
val ink=Color(0xff071014);val surf=Color(0xff0c1c21);val mint=Color(0xff55e6bc);val amber=Color(0xffffc857)
@Composable fun UI(overlay:()->Unit,access:()->Unit,bubble:()->Unit){var env by remember{mutableStateOf(Env.DEMO)};var risk by remember{mutableStateOf(false)};var status by remember{mutableStateOf("STOPPED")};var mapping by remember{mutableStateOf("NOT MAPPED")};var target by remember{mutableStateOf("Not detected")};var note by remember{mutableStateOf("Observe → identify → verify → act → verify → persist")};MaterialTheme(colorScheme=darkColorScheme(primary=mint,background=ink,surface=surf)){Scaffold(topBar={Surface{Row(Modifier.fillMaxWidth().padding(16.dp)){Column(Modifier.weight(1f)){Text("AEGIS",fontWeight=FontWeight.Black,style=MaterialTheme.typography.headlineSmall);Text("Automation control plane",color=Color.Gray)};Badge(env)}}}){p->Column(Modifier.padding(p).fillMaxSize().verticalScroll(rememberScrollState()).padding(16.dp),verticalArrangement=Arrangement.spacedBy(12.dp)){Card("$status",note);Card("SYSTEM SIGNALS"){Signal("Environment",env.name);Signal("Target",target);Signal("Mapping",mapping);Signal("Connection","OBSERVE ONLY")};Row(horizontalArrangement=Arrangement.spacedBy(8.dp)){Button({try{val(pkg,c)=Inspector.scan();target=pkg;mapping=if(Mapper.valid(c))"VALID" else "CONFIRM REQUIRED";status="PAUSED";note="${c.size} candidates found. Confirm medium confidence; ambiguity never activates."}catch(e:Exception){status="UNKNOWN";note=e.message?:"Unavailable"}},Modifier.weight(1f)){Text("MAP CONTROLS")};OutlinedButton(bubble,Modifier.weight(1f)){Text("BUBBLE")}};Card("PERMISSIONS"){Row{TextButton(overlay){Text("OVERLAY SETTINGS")};TextButton(access){Text("ACCESSIBILITY")}}};Card("ENVIRONMENT"){Text("DEMO is default. REAL requires risk acknowledgment and a deliberate START after every restart.",color=Color.Gray);Row(horizontalArrangement=Arrangement.spacedBy(8.dp)){FilterChip(env==Env.DEMO,{env=Env.DEMO;status="STOPPED"},{Text("DEMO")});FilterChip(env==Env.REAL,{risk=true},{Text("REAL")})}};PanelCard("PANEL 1","1.00","10×","2.00×");PanelCard("PANEL 2","10.00","10×","3.00×");Card("SESSION"){Row(horizontalArrangement=Arrangement.spacedBy(7.dp)){Button({if(mapping=="VALID"){status="RUNNING";note="Monitoring. Every action still requires fresh preflight and result verification."}else{status="PAUSED";note="Blocked: mapping invalid or unconfirmed."}},Modifier.weight(1f)){Text("START")};OutlinedButton({status="PAUSED";note="New actions paused; observation continues."},Modifier.weight(1f)){Text("PAUSE")};OutlinedButton({status="STOPPED";note="Stopped and persisted."},Modifier.weight(1f)){Text("STOP")}}}}};if(risk)AlertDialog(onDismissRequest={risk=false},confirmButton={Button(onClick={env=Env.REAL;status="STOPPED";note="REAL acknowledged, not started. Validate target, mapping, limits and press START.";risk=false}){Text("I UNDERSTAND THE RISKS")}},dismissButton={TextButton(onClick={risk=false}){Text("CANCEL")}},title={Text("REAL MODE RISK")},text={Text("Automated actions may cause financial loss. No profit is guaranteed. Technical failure, incorrect configuration, or mapping errors can cause unintended actions. You are responsible for review and operation. Acknowledgment does not start automation.")})}}
@Composable fun Badge(e:Env){Surface(color=if(e==Env.REAL)amber.copy(.2f)else mint.copy(.15f),shape=RoundedCornerShape(30.dp)){Text("ENV • ${e.name}",color=if(e==Env.REAL)amber else mint,fontWeight=FontWeight.Bold,modifier=Modifier.padding(12.dp,8.dp))}}
@Composable fun Card(title:String,body:@Composable ColumnScope.()->Unit){Surface(color=surf,shape=RoundedCornerShape(16.dp)){Column(Modifier.fillMaxWidth().padding(16.dp),verticalArrangement=Arrangement.spacedBy(8.dp)){Text(title,color=mint,fontWeight=FontWeight.Bold);body()}}};@Composable fun Card(title:String,text:String)=Card(title){Text(text,color=Color.LightGray)}
@Composable fun Signal(a:String,b:String){Row(Modifier.fillMaxWidth()){Text(a,color=Color.Gray,modifier=Modifier.weight(1f));Text(b,fontWeight=FontWeight.SemiBold)}}
@Composable fun PanelCard(n:String,s:String,f:String,c:String)=Card(n){Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.SpaceBetween){Metric("CURRENT",s);Metric("FACTOR",f);Metric("CASH OUT",c)};Text("READY • level 0 • no open action",color=Color.Gray)};@Composable fun Metric(k:String,v:String){Column{Text(k,color=Color.Gray,style=MaterialTheme.typography.labelSmall);Text(v,fontWeight=FontWeight.Bold)}}
